function ProductCard({ name, price }) {
  return (
    <article className="card">
      <b>{name}</b>
      <span> {price}원</span>
    </article>
  );
}

function App() {
  return (
    <main>
      <ProductCard name="셔츠" price={39000} />
      <ProductCard name="모자" price={15000} />
    </main>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

